using EduManageLms.Api.Application; using EduManageLms.Api.Common; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace EduManageLms.Api.Controllers; [ApiController][Route("api/v1/lecturer")][Authorize(Roles="Lecturer")]
public sealed class LecturerController(IGradebookService svc):ControllerBase{[HttpGet("classes/{id}/gradebook")]public async Task<ActionResult<ApiResponse<GradebookDto>>> Gradebook(string id,CancellationToken ct)=>Ok(ApiResponse<GradebookDto>.Ok(await svc.GetAsync(User.LecturerCode()!,id,ct)));[HttpPut("classes/{id}/grades")]public async Task<ActionResult<ApiResponse<object>>> Update(string id,GradeUpdateRequest r,CancellationToken ct){await svc.UpdateAsync(User.LecturerCode()!,id,r,User.UserId(),ct);return Ok(ApiResponse<object>.Ok(new{},r.Publish?"Công bố điểm thành công":"Lưu nháp thành công"));}}
